import axios from 'axios';

// Backend adresi, root (/) path'ine istek atacak şekilde güncellendi
const API_URL = 'http://localhost:8000';

/**
 * İşlem (Transaction) Servisleri
 */

// Son işlemleri listeler (Dashboard ana tablosu için)
export const getTransactions = () => axios.get(`${API_URL}/recent`);

// Belirli bir kullanıcı için işlem geçmişini ve risk durumunu getirir (Yönerge İsteri)
export const getUserStatus = (userId) => axios.get(`${API_URL}/users/${userId}/status`);

// Belirli bir zaman aralığında tespit edilen şüpheli (fraud) işlemleri listeler (Yönerge İsteri)
export const getRecentFrauds = () => axios.get(`${API_URL}/frauds/recent`);

/**
 * MCP (Model Context Protocol) Servisleri 
 * (Yapay zeka ajanlarının sorgulayabilmesi için araçlar)
 */

export const mcpGetRecentFrauds = () => axios.get(`${API_URL}/mcp/frauds`);
export const mcpCheckUserStatus = (userId) => axios.get(`${API_URL}/mcp/user/${userId}`);

export default {
    getTransactions,
    getUserStatus,
    getRecentFrauds,
    mcpGetRecentFrauds,
    mcpCheckUserStatus
};
